import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bir görselin köşelerini yuvarlamak dakikalar sürer. Program kurmazsınız, fotoğrafınız cihazınızdan ayrılmaz ve sonunda modern görünümlü bir görsel indirirsiniz.</p>\n<p>Bu yazı, işlemi beş adımda anlatıyor. İster avatar ister kart yapın, adımlar aynıdır.</p>\n<p>Sonunda yarıçapı nasıl ayarlayacağınızı, köşe başına modu nasıl kullanacağınızı ve daire kısayolunu öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: biçimi seçin</h2>\n<p>Önce biçimi belirleyin: hafif yuvarlak mı, daire mi, hap mı? Biçim, yarıçapı belirler.</p>\n<p>Fotoğrafı seçin. Kare fotoğraf daire için, dikdörtgen fotoğraf hap için uygundur.</p>\n<p>Formatı belirleyin. Saydam köşeler için PNG gerekir; JPG köşeleri beyaz doldurur.</p>\n<h2 id=\"step-by-step\">Görsel köşelerini beş adımda yuvarlamak</h2>\n<p>Önce aracı açıp görseli yükleyin. Önizlemede fotoğrafın tamamını görün.</p>\n<p>Sonra yarıçapı ayarlayın ve dolguyu seçin. Önizleme anında güncellenir.</p>\n<p>Son olarak formatı seçip indirin. Önizlemeyi atlamayın; yanlış yarıçap zaman kaybıdır.</p>\n<ol>\n<li>Köşe yuvarlama aracını açın ve fotoğrafınızı yükleyin.</li>\n<li>Yarıçap kaydırıcısıyla köşelerin yuvarlaklığını ayarlayın.</li>\n<li>Gerekirse köşe başına moduyla tek köşeyi ayarlayın.</li>\n<li>Saydam ya da düz dolgu seçin.</li>\n<li>PNG olarak indirin; saydamlık korunur.</li>\n</ol>\n<h2 id=\"setting-radius\">Köşe yarıçapını ayarlamak</h2>\n<p>Yarıçap kaydırıcısıyla köşelerin yuvarlaklığını ayarlayın. Küçük yarıçap hafif, büyük yarıçap belirgin yuvarlama yapar.</p>\n<p>Kartlar için yüzde 5-10 kullanın. Modern görünüm için bu aralık yeterlidir.</p>\n<p>Daire için yüzde 50 kullanın. Kare fotoğraf, daireye döner.</p>\n<h2 id=\"per-corner-mode\">Köşe başına modunu kullanmak</h2>\n<p>Köşe başına modu, her köşeyi ayrı ayarlar. Yalnızca üst köşeleri yuvarlayabilirsiniz.</p>\n<p>Bu mod, kart tasarımlarında kullanılır. Kartın üstü yuvarlak, altı keskin olabilir.</p>\n<p>Köşeleri tek tek ayarlamakla uğraşmayın; çoğu işte hepsini eşit ayarlamak yeterlidir.</p>\n<h2 id=\"full-circle-shortcut\">Tam daire ve hap kısayolu</h2>\n<p>Tam daire düğmesi, yarıçapı yüzde 50 yapar. Kare fotoğraf anında daire olur.</p>\n<p>Hap düğmesi, dikdörtgeni hap biçimine çevirir. Düğme ve etiketlerde kullanılır.</p>\n<p>Kısayolları kullandıktan sonra önizlemeyi kontrol edin. Yüz merkeze alınmış olmalıdır.</p>\n<h2 id=\"choosing-fill\">Saydam ya da düz dolgu seçmek</h2>\n<p>Saydam dolgu seçin; köşeler görünmez olur ve görsel, hangi zemine koyarsanız koyun temiz durur.</p>\n<p>Düz dolgu seçerseniz köşeler seçtiğiniz renkle dolar; beyaz dolgu, beyaz sayfada fark edilmez.</p>\n<p>Saydam dolgu için PNG kullanın. JPG saydamlığı desteklemez.</p>\n<h2 id=\"choosing-format\">Dışa aktarma formatını seçmek</h2>\n<p>Saydam köşeler için PNG kullanın. Köşeler her zeminde temiz görünür.</p>\n<p>Web için WebP kullanın. WebP saydamlığı destekler ve daha küçüktür.</p>\n<p>JPG kullanmayın. JPG köşeleri beyaz doldurur; yuvarlama kaybolur.</p>\n<h2 id=\"previewing\">İndirmeden önce önizleme</h2>\n<p>Her zaman önizlemeyi kontrol edin. Köşelerin yuvarlaklığı ve dolgu doğru olmalıdır.</p>\n<p>Önizlemede saydam alanlar damalı desenle görünür. Köşeler temiz olmalıdır.</p>\n<p>Şüphede kalırsanız yarıçapı azaltın. Hafif yuvarlama, her zaman güvenli seçimdir.</p>\n<h2 id=\"rounding-for-avatar\">Avatar için köşe yuvarlamak</h2>\n<p>Profil fotoğrafı hazırlıyorsanız kareyi yüzde 50 yarıçapla daire yapın; avatarlar genelde daire biçiminde istenir.</p>\n<p>Yüzü merkeze alın. Daire köşeleri keser; yüz çerçevenin dışında kalmamalıdır.</p>\n<p>Avatar için yüksek çözünürlüklü fotoğrafla başlayın; küçük kaynaktan büyütülen avatar bulanık çıkar.</p>\n<h2 id=\"rounding-for-cards\">Kart ve arayüz için köşe yuvarlamak</h2>\n<p>Kartlar hafif yuvarlak köşe ister. Yüzde 5-10 yarıçap, modern görünür.</p>\n<p>Tüm kartlarda aynı yarıçapı kullanın. Tutarlılık arayüzü profesyonel gösterir.</p>\n<p>Yarıçapı ölçülü tutun; aşırı yuvarlanmış bir kart, tasarımı amatör gösterir.</p>\n<h2 id=\"rounding-screenshots\">Ekran görüntüsünde köşe yuvarlamak</h2>\n<p>Ekran görüntüleri hafif yuvarlak köşeyle modern görünür. Yüzde 5-10 yarıçap yeterlidir.</p>\n<p>Saydam köşeler için PNG olarak indirin. JPG köşeleri beyaz doldurur.</p>\n<p>Ekran görüntüleri PNG olarak kaydedilmelidir. Kayıpsız yapı, metni korur.</p>\n<h2 id=\"rounding-on-mobile\">Telefon ve tablette köşe yuvarlamak</h2>\n<p>Telefonunuzda tarayıcıyı açın, köşe yuvarlama aracına fotoğrafı yükleyin ve yarıçap kaydırıcısını istediğiniz değere getirin.</p>\n<p>Telefonda ince yarıçap ayarı yapmak zordur; hassas bir değer istiyorsanız bilgisayardan çalışın.</p>\n<p>İndirilenler, cihazın İndirilenler klasörüne kaydedilir. Tarayıcının indirme listesi de yardımcı olur.</p>\n<h2 id=\"troubleshooting\">Köşe yuvarlamada yaygın sorunları çözmek</h2>\n<p>Köşeler beyaz görünüyorsa format JPG'dir. PNG olarak indirin; saydamlık korunur.</p>\n<p>Kenarlar dişli görünüyorsa çözünürlük düşüktür. Daha yüksek çözünürlüklü kaynak kullanın.</p>\n<p>Görsel değişmiyorsa sayfayı yenileyin. Tarayıcı sorunu, genellikle yenilemeyle çözülür.</p>\n<h2 id=\"combining-with-border\">Yuvarlak köşeleri çerçeveyle birleştirmek</h2>\n<p>Köşeleri yuvarladıktan sonra çerçeve de ekleyebilirsiniz; çerçeve, yuvarlak köşenin kıvrımını takip eder.</p>\n<p>Çerçeve ve fotoğraf yarıçapını birlikte ayarlayın. Dış yarıçap ile iç yarıçap uyumlu olmalıdır.</p>\n<p>Çerçeve ekliyorsanız ince tutun; kalın çerçeve, yuvarlak köşenin zarifliğini boğar.</p>\n<h2 id=\"quick-tips\">Daha iyi yuvarlak köşeler için hızlı ipuçları</h2>\n<p>Yarıçapı hedefe göre seçin. Kart için yüzde 5-10, avatar için yüzde 50 kullanın.</p>\n<p>Saydam köşeler için PNG kullanın. JPG yuvarlamayı bozar.</p>\n<p>Tutarlı olun. Tüm kartlarda aynı yarıçapı kullanın.</p>\n<h2 id=\"rounding-for-social-post\">Sosyal medya gönderisi için köşe yuvarlamak</h2>\n<p>Sosyal medya görsellerinde hafif yuvarlama kullanın. Yüzde 5-10 yarıçap, modern görünür.</p>\n<p>Tüm gönderilerde aynı yarıçapı kullanın. Tutarlılık, profilinizi tanınır kılar.</p>\n<p>Saydam köşeler için PNG kullanın. Platform, saydamlığı korur.</p>\n<h2 id=\"rounding-for-presentation\">Sunum için köşe yuvarlamak</h2>\n<p>Sunum görsellerinde hafif yuvarlama kullanın. Köşeler, slaytta yumuşak görünür.</p>\n<p>Beyaz ya da açık dolgu kullanın. Koyu dolgu, slaytta ağır görünür.</p>\n<p>Sunumdan önce görselleri deneyin. Dosyaların açıldığından emin olun.</p>\n<p>Adım adım ilerleyin ve her görseli indirmeden önce kontrol edin. Karşılaştırma için <a href=\"/tr/blog/yuvarlatilmis-koseler-vs-daire-kirpma\">yuvarlak köşeler ve daire kırpma karşılaştırmasına</a> bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-kose-yuvarla-rehberi\">köşe yuvarlama kılavuzunda</a>. Kırpma için <a href=\"/tr/gorsel-kirp\">görsel kırpıcı</a>, çerçeve için <a href=\"/tr/gorsel-cerceve-olusturucu\">görsel çerçeve oluşturucu</a> hazırdır; araç ise <a href=\"/tr/gorsel-kose-yuvarla\">köşe yuvarlama</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Telefonda bir fotoğrafın köşelerini nasıl yuvarlarım?","answer":"Köşe yuvarlama aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve yarıçap kaydırıcısını ayarlayın. Saydam köşeler için PNG olarak indirin. Hassas yarıçap için bilgisayarı tercih edin."},{"question":"Kart görseli için en iyi yarıçap hangisi?","answer":"Yüzde 5-10 arası en iyisidir; modern görünür ve içeriği boğmaz. Tüm kartlarda aynı yarıçapı kullanın. Çok yuvarlak kart amatör görünür; yüzde 20'nin üzeri genellikle fazladır."},{"question":"JPG görselin köşelerini yuvarlayabilir miyim?","answer":"Evet, yuvarlayabilirsiniz ama köşeler beyaz dolar; JPG saydamlığı desteklemez. Beyaz sayfada bu fark edilmez. Saydam köşeler için PNG ya da WebP olarak indirin."},{"question":"Görseli değiştirmeden yarıçap ayarlarımı nasıl korurum?","answer":"Aynı oturumda yeni görsel yükleyin; ayarlar genellikle korunur. Sayfayı yenilerseniz ayarlar sıfırlanır. Ayarlarınızı not edin; yarıçap değerini kaydedin."},{"question":"Yuvarlak köşelerim neden dişli görünüyor?","answer":"Çünkü kaynak çözünürlük düşüktür; düşük çözünürlükte eğri kenar dişli görünür. Daha yüksek çözünürlüklü kaynak kullanın. Modern araçlar kenar yumuşatmayı otomatik yapar."},{"question":"Köşeleri yuvarlamak fotoğrafımın genişliğini ve yüksekliğini değiştirir mi?","answer":"Hayır. Yuvarlama yalnızca köşeleri keser; boyut aynı kalır. Toplam piksel sayısı değişmez. Çerçeve eklemek boyutu büyütür; yuvarlama büyütmez."}];
